SYSTEM_HTML = '{% extends "corporate_information_center/base.html" %}\n{% set active_tab=\'system\' %}\n{% block cic_content %}\n<style>\n/* BYS360_CORPORATE_INFORMATION_CENTER_V3_0_PHASE7_7_RELEASE_CLEAN_UI */\n.cic-release-clean{--r:#8B0000;--r2:#6b0000;--ink:#172033;--muted:#667085;--line:rgba(23,32,51,.10);--soft:#fff7f7;display:grid;gap:18px}.cic-release-clean a{color:inherit;text-decoration:none}.release-hero{position:relative;overflow:hidden;border-radius:30px;padding:30px;border:1px solid rgba(139,0,0,.16);background:linear-gradient(135deg,#fff,#fff7f7 55%,#f7f8fb);box-shadow:0 26px 70px rgba(15,23,42,.08)}.release-hero:before{content:"";position:absolute;right:-80px;top:-120px;width:300px;height:300px;border-radius:999px;background:radial-gradient(circle,rgba(139,0,0,.13),transparent 65%)}.release-hero:after{content:"";position:absolute;left:-120px;bottom:-160px;width:360px;height:360px;border-radius:999px;background:radial-gradient(circle,rgba(139,0,0,.07),transparent 60%)}.release-hero>*{position:relative;z-index:1}.release-eyebrow{display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(139,0,0,.18);background:#fff;border-radius:999px;padding:8px 12px;color:var(--r);font-size:12px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}.release-title{margin:14px 0 8px;font-size:clamp(28px,3vw,44px);line-height:1.05;font-weight:950;color:var(--ink);letter-spacing:-.04em}.release-lead{max-width:920px;color:#475467;font-size:15.5px;line-height:1.75;margin:0}.release-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}.release-btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;border-radius:15px;padding:12px 16px;font-weight:900;border:1px solid transparent;box-shadow:0 14px 30px rgba(139,0,0,.10);transition:.16s ease}.release-btn.primary{background:var(--r);color:#fff}.release-btn.primary:hover{background:var(--r2);color:#fff;transform:translateY(-1px)}.release-btn.secondary{background:#fff;color:var(--r);border-color:rgba(139,0,0,.22)}.release-btn.secondary:hover{border-color:rgba(139,0,0,.45);box-shadow:0 16px 36px rgba(15,23,42,.08)}.release-pill-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.release-pill{display:inline-flex;gap:8px;align-items:center;border:1px solid rgba(23,32,51,.08);background:#fff;border-radius:999px;padding:8px 11px;color:#344054;font-size:12.5px;font-weight:850}.release-pill.ok{color:#027a48;background:#ecfdf3;border-color:rgba(2,122,72,.15)}.release-kpi-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.release-kpi{border-radius:24px;background:#fff;border:1px solid var(--line);box-shadow:0 16px 42px rgba(15,23,42,.06);padding:18px;min-height:132px;display:flex;flex-direction:column;justify-content:space-between}.release-kpi .icon{width:44px;height:44px;border-radius:16px;background:var(--soft);color:var(--r);display:flex;align-items:center;justify-content:center;font-size:18px}.release-kpi strong{font-size:23px;color:var(--ink);line-height:1.15;letter-spacing:-.02em}.release-kpi span{font-size:13px;color:var(--muted);line-height:1.45}.release-section{border-radius:28px;background:rgba(255,255,255,.95);border:1px solid var(--line);box-shadow:0 18px 54px rgba(15,23,42,.07);padding:22px}.release-section-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:16px}.release-section h2{margin:0;color:var(--ink);font-size:22px;font-weight:950;letter-spacing:-.025em}.release-section p{margin:6px 0 0;color:var(--muted);line-height:1.6}.release-timeline{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.release-step{position:relative;border:1px solid rgba(139,0,0,.12);background:linear-gradient(180deg,#fff,#fffafa);border-radius:22px;padding:18px}.release-step .num{width:34px;height:34px;border-radius:13px;background:var(--r);color:#fff;font-weight:950;display:flex;align-items:center;justify-content:center;margin-bottom:12px}.release-step h3{margin:0 0 7px;color:var(--ink);font-size:17px;font-weight:950}.release-step p{font-size:13px}.release-check-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.release-check{display:flex;gap:12px;align-items:flex-start;border:1px solid rgba(23,32,51,.08);border-radius:18px;background:#fff;padding:14px}.release-check .mark{width:28px;height:28px;border-radius:11px;background:#ecfdf3;color:#027a48;display:flex;align-items:center;justify-content:center;flex:0 0 auto}.release-check strong{display:block;color:var(--ink);font-weight:950}.release-check small{display:block;color:var(--muted);line-height:1.45;margin-top:3px}.release-alert{display:flex;gap:14px;align-items:flex-start;border-radius:22px;padding:16px;border:1px solid rgba(181,71,8,.18);background:#fffaeb;color:#7a2e0e}.release-alert .icon{width:38px;height:38px;border-radius:15px;background:#fff7dc;display:flex;align-items:center;justify-content:center;flex:0 0 auto;color:#b54708}.release-alert strong{display:block;margin-bottom:4px}.release-command{background:#101828;color:#fff;border-radius:18px;padding:16px;font-size:13px;line-height:1.65;white-space:pre-wrap;overflow:auto}.release-soft-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.release-mini-card{border:1px solid var(--line);border-radius:20px;background:#fff;padding:16px}.release-mini-card h3{font-size:16px;font-weight:950;margin:0 0 8px;color:var(--ink)}.release-mini-card ul{margin:0;padding-left:18px;color:#475467;line-height:1.75;font-size:13.5px}.release-details{border:1px solid var(--line);border-radius:22px;background:#fff;overflow:hidden}.release-details summary{cursor:pointer;list-style:none;padding:16px 18px;font-weight:950;color:var(--ink);display:flex;align-items:center;justify-content:space-between}.release-details summary::-webkit-details-marker{display:none}.release-details summary:after{content:"+";font-size:22px;color:var(--r)}.release-details[open] summary:after{content:"–"}.release-details .body{border-top:1px solid var(--line);padding:18px}.release-form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.release-form-grid label{font-weight:850;color:#344054;font-size:13px}.release-form-grid input{margin-top:7px}.release-submit-row{display:flex;justify-content:flex-end;margin-top:14px}.release-watermark{display:inline-flex;align-items:center;gap:8px;color:#98a2b3;font-size:12px;font-weight:800;margin-top:3px}@media(max-width:1100px){.release-kpi-grid,.release-timeline,.release-soft-tabs{grid-template-columns:1fr 1fr}.release-form-grid{grid-template-columns:1fr}}@media(max-width:760px){.release-kpi-grid,.release-timeline,.release-check-grid,.release-soft-tabs{grid-template-columns:1fr}.release-hero{padding:22px}.release-section{padding:18px}.release-section-head{display:block}.release-actions .release-btn{width:100%}}\n</style>\n\n<section id="release" class="cic-release-clean">\n  <div class="release-hero">\n    <span class="release-eyebrow"><i class="fa-solid fa-shield-halved"></i> Canlı Geçiş Hazırlığı</span>\n    <h1 class="release-title">Kurumsal Bilgilendirme Merkezi yayına hazır.</h1>\n    <p class="release-lead">Bu ekran yalnızca karar ve kontrol için sadeleştirildi. Önce pilot gönderim yapılır, loglar kontrol edilir, ardından gerçek gönderim bilinçli onayla açılır. Teknik ayrıntılar sayfanın altındaki kapalı alanda tutulur.</p>\n    <div class="release-actions">\n      <a class="release-btn primary" href="/dashboard/kurumsal-bilgilendirme/test"><i class="fa-solid fa-paper-plane"></i> Pilot test ekranına git</a>\n      <a class="release-btn secondary" href="/dashboard/kurumsal-bilgilendirme/loglar"><i class="fa-solid fa-clock-rotate-left"></i> Gönderim geçmişini incele</a>\n      <a class="release-btn secondary" href="/dashboard/kurumsal-bilgilendirme/sablonlar"><i class="fa-solid fa-envelope-open-text"></i> Şablonları kontrol et</a>\n    </div>\n    <div class="release-pill-row">\n      <span class="release-pill ok"><i class="fa-solid fa-circle-check"></i> Faz 6 UAT tamamlandı</span>\n      <span class="release-pill ok"><i class="fa-solid fa-circle-check"></i> CSRF koruması aktif</span>\n      <span class="release-pill"><i class="fa-solid fa-lock"></i> Gerçek gönderim onaylı</span>\n      <span class="release-pill"><i class="fa-solid fa-user-check"></i> Pilot test zorunlu</span>\n    </div>\n  </div>\n\n  <div class="release-kpi-grid">\n    <div class="release-kpi"><div class="icon"><i class="fa-solid fa-route"></i></div><strong>3 adım</strong><span>Canlı geçiş; pilot test, log kontrolü ve onaylı gönderim şeklinde yürür.</span></div>\n    <div class="release-kpi"><div class="icon"><i class="fa-solid fa-users-viewfinder"></i></div><strong>Pilot önce</strong><span>Toplu gönderimden önce sınırlı alıcıyla gerçek sonuç doğrulanır.</span></div>\n    <div class="release-kpi"><div class="icon"><i class="fa-solid fa-clipboard-check"></i></div><strong>İzlenebilir</strong><span>Gönderim, kullanıcı, sonuç ve hata kayıtları log ekranında takip edilir.</span></div>\n    <div class="release-kpi"><div class="icon"><i class="fa-solid fa-rotate-left"></i></div><strong>Geri dönüş</strong><span>Sorun görülürse kuru çalışma moduna dönülür ve gönderim durdurulur.</span></div>\n  </div>\n\n  <div class="release-section">\n    <div class="release-section-head"><div><h2>Canlı geçiş sırası</h2><p>Karmaşık teknik adımlar yerine sadece uygulanacak karar sırası gösterilir.</p></div><span class="release-watermark"><i class="fa-solid fa-layer-group"></i> BYS360 Faz 7.7</span></div>\n    <div class="release-timeline">\n      <div class="release-step"><div class="num">1</div><h3>Pilot gönderim</h3><p>Test Merkezi’nden yalnızca pilot alıcıya gönderim yapılır. Konu, şablon ve bağlantılar kontrol edilir.</p></div>\n      <div class="release-step"><div class="num">2</div><h3>Log doğrulama</h3><p>Gönderim Geçmişi ekranında başarılı, başarısız ve atlanan kayıtlar incelenir.</p></div>\n      <div class="release-step"><div class="num">3</div><h3>Kontrollü yayın</h3><p>Gerçek gönderim yalnızca sorumlu kullanıcı onayıyla ve alıcı özeti görülerek başlatılır.</p></div>\n    </div>\n  </div>\n\n  <div class="release-section">\n    <div class="release-section-head"><div><h2>Yönetici kontrol listesi</h2><p>Canlıya geçmeden önce kırmızı alarm yaratabilecek başlıklar sade şekilde izlenir.</p></div><a class="release-btn secondary" href="/dashboard/kurumsal-bilgilendirme/sistem"><i class="fa-solid fa-rotate"></i> Sistem durumunu yenile</a></div>\n    <div class="release-check-grid">\n      <div class="release-check"><div class="mark"><i class="fa-solid fa-check"></i></div><div><strong>SMTP bilgileri kontrol edildi</strong><small>Gönderici adresi, kullanıcı adı ve sunucu bilgisi doğru olmalı.</small></div></div>\n      <div class="release-check"><div class="mark"><i class="fa-solid fa-check"></i></div><div><strong>Şablonlar boş değil</strong><small>Sabah, gün ortası ve akşam metinleri kurumsal dilde olmalı.</small></div></div>\n      <div class="release-check"><div class="mark"><i class="fa-solid fa-check"></i></div><div><strong>Alıcı grubu doğrulandı</strong><small>Pasif/e-postasız kayıtlar toplu gönderimden önce ayıklanmalı.</small></div></div>\n      <div class="release-check"><div class="mark"><i class="fa-solid fa-check"></i></div><div><strong>Log oluşumu test edildi</strong><small>Başarılı ve başarısız denemeler geçmiş ekranında görünmeli.</small></div></div>\n    </div>\n  </div>\n\n  <div class="release-alert"><div class="icon"><i class="fa-solid fa-triangle-exclamation"></i></div><div><strong>Gerçek gönderim uyarısı</strong> Toplu gerçek gönderimden önce alıcı sayısı, konu, şablon ve kuru çalışma durumu son kez görülmelidir. Pilot test yapılmadan kurum geneline gönderim başlatılmamalıdır.</div></div>\n\n  <div class="release-section">\n    <div class="release-section-head"><div><h2>Kullanım özeti</h2><p>Kullanıcıya gösterilecek ana mantık üç sade alanda tutulur.</p></div></div>\n    <div class="release-soft-tabs">\n      <div class="release-mini-card"><h3>Görev</h3><ul><li>Gönderilecek görev seçilir.</li><li>Çalışma zamanı ve hedef kitle kontrol edilir.</li><li>Durum aktif/pasif olarak izlenir.</li></ul></div>\n      <div class="release-mini-card"><h3>Alıcı</h3><ul><li>Birim veya kişi bazlı seçim yapılır.</li><li>E-postası olmayan kayıtlar kontrol edilir.</li><li>Pilot grup önce denenir.</li></ul></div>\n      <div class="release-mini-card"><h3>Gönderim</h3><ul><li>Önce kuru çalışma yapılır.</li><li>Sonra pilot gerçek gönderim yapılır.</li><li>Log temizse canlı gönderim başlatılır.</li></ul></div>\n    </div>\n  </div>\n\n  <details class="release-details">\n    <summary>Teknik ayarlar ve zamanlanmış iş komutu</summary>\n    <div class="body">\n      <form method="post" class="release-config-form">\n        {% if csrf_token is defined %}<input type="hidden" name="csrf_token" value="{{ csrf_token() }}">{% endif %}\n        <div class="release-form-grid">\n          <label>Konum adı<input class="cic-input" name="location_name" value="{{ config.location_name|default(\'\', true) }}"></label>\n          <label>Enlem<input class="cic-input" name="latitude" value="{{ config.latitude|default(\'\', true) }}"></label>\n          <label>Boylam<input class="cic-input" name="longitude" value="{{ config.longitude|default(\'\', true) }}"></label>\n        </div>\n        <div class="release-submit-row"><button class="release-btn primary" type="submit"><i class="fa-solid fa-floppy-disk"></i> Teknik ayarları kaydet</button></div>\n      </form>\n      <div style="height:14px"></div>\n      <div class="release-command">powershell -ExecutionPolicy Bypass -File .\\scripts\\windows\\install_bys360_corporate_information_tasks_v3_0.ps1 -ProjectRoot "C:\\bys360\\project"</div>\n    </div>\n  </details>\n</section>\n{% endblock %}\n'

def sanitize_base(base: Path):
    if not base.exists():
        return []
    text = base.read_text(encoding='utf-8')
    original = text
    text = text.replace("\">') }}?v=2_15_18\"", '"')
    text = text.replace("\">') }}?v=2_15_18", '"')
    text = text.replace("') }}?v=2_15_18\"", '"')
    text = re.sub(r"<link[^\n]*corporate_information_center_v3_0_phase7\.css[^\n]*>\s*'\)\s*}}\?v=2_15_18\"?>", "<link rel=\"stylesheet\" href=\"{{ url_for('static', filename='css/corporate_information_center_v3_0_phase7.css') }}?v=2_15_21\">", text)
    if "corporate_information_center_v3_0_phase7_7_release_clean.css" not in text:
        marker = "{% endblock %}"
        link = "<link rel=\"stylesheet\" href=\"{{ url_for('static', filename='css/corporate_information_center_v3_0_phase7_7_release_clean.css') }}?v=2_15_27\">\n"
        pos = text.find(marker)
        if pos != -1:
            text = text[:pos] + link + text[pos:]
    if text != original:
        base.write_text(text, encoding='utf-8')
        return [str(base)]
    return []

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('-ProjectRoot','--ProjectRoot', default='C:/bys360/project')
    args = parser.parse_args()
    root = Path(args.ProjectRoot)
    system = root/'app/templates/corporate_information_center/system.html'
    base = root/'app/templates/corporate_information_center/base.html'
    css = root/'app/static/css/corporate_information_center_v3_0_phase7_7_release_clean.css'
    backup_dir = root/'backups'/'corporate_information_center_phase7_7_release_clean_ui'
    backup_dir.mkdir(parents=True, exist_ok=True)
    changed=[]
    if system.exists(): shutil.copy2(system, backup_dir/'system.html.bak')
    if base.exists(): shutil.copy2(base, backup_dir/'base.html.bak')
    system.parent.mkdir(parents=True, exist_ok=True)
    system.write_text(SYSTEM_HTML, encoding='utf-8')
    changed.append(str(system))
    css.parent.mkdir(parents=True, exist_ok=True)
    css.write_text(f"/* {VERSION}: styles are embedded in system.html intentionally for local reliability. */\n", encoding='utf-8')
    changed.append(str(css))
    changed += sanitize_base(base)
    print(f"{VERSION}_APPLY_OK")
    print("Güncellenen dosyalar:")
    for item in changed:
        try: print(" - "+str(Path(item).relative_to(root)))
        except Exception: print(" - "+item)
    return 0
if __name__ == '__main__':
    raise SystemExit(main())
